PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS login_attempts(id INTEGER PRIMARY KEY, email TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS institutions(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, acronym TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS modules(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, institution_id INTEGER NOT NULL REFERENCES institutions(id), programme TEXT NOT NULL, year INTEGER NOT NULL CHECK(year BETWEEN 1 AND 7), role TEXT NOT NULL DEFAULT 'student', active INTEGER NOT NULL DEFAULT 1, profile TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS connections(id INTEGER PRIMARY KEY, sender INTEGER NOT NULL REFERENCES users(id), receiver INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending', created TEXT NOT NULL, CHECK(sender != receiver));
CREATE UNIQUE INDEX IF NOT EXISTS connection_pair ON connections(min(sender,receiver),max(sender,receiver));
CREATE TABLE IF NOT EXISTS study_sessions(id INTEGER PRIMARY KEY, creator INTEGER NOT NULL REFERENCES users(id), peer INTEGER NOT NULL REFERENCES users(id), module TEXT NOT NULL, topic TEXT NOT NULL, starts TEXT NOT NULL, duration INTEGER NOT NULL, location TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', CHECK(creator != peer));
CREATE TABLE IF NOT EXISTS feedback(id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES study_sessions(id), author INTEGER NOT NULL REFERENCES users(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), useful INTEGER NOT NULL, again INTEGER NOT NULL, comments TEXT NOT NULL, UNIQUE(session_id,author));
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), message TEXT NOT NULL, created TEXT NOT NULL, seen INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS matches(user_id INTEGER REFERENCES users(id), peer_id INTEGER REFERENCES users(id), score INTEGER NOT NULL, reasons TEXT NOT NULL, updated TEXT NOT NULL, PRIMARY KEY(user_id,peer_id));
